#!/bin/bash
# slotconf.sh -- the peripheral slot's conformance, ref's side (WORKER15; tests/ref/SlotConf.java, tests/test_slotconf.cpp).
# Needs a JDK. Nothing in sim/ref is written: ref and the driver are compiled into a scratch directory.
#   slotconf.sh --fixtures        write tests/slotconf/seedN.{script,obs}.gz (seeds 1-5, 3,000 cycles each)
#   slotconf.sh --check           replay the committed scripts on ref; its observations must equal the committed ones
#   slotconf.sh --long N C BIN    seeds 6..N of C cycles each, generated by ref and replayed by BIN (build/.../slotconf)
set -u
SIM=$(cd "$(dirname "$0")/../.." && pwd); FIX="$SIM/tests/slotconf"; SEEDS="1 2 3 4 5"
build() {
  rm -rf "$1"; mkdir -p "$1"
  javac --release 17 -nowarn -d "$1" "$SIM"/ref/meshsim/src/*.java "$SIM"/ref/meshsim/test/*.java 2>&1 | grep -v '^Note:'
  javac --release 17 -nowarn -d "$1" -cp "$1" "$SIM"/tests/ref/SlotConf.java 2>&1 | grep -v '^Note:'
  [ -f "$1/SlotConf.class" ] || { echo "slotconf: the driver did not compile"; exit 2; }
}
B=$(mktemp -d); build "$B"; R="$SIM/ref/meshsim"
case "${1:-}" in
  --fixtures)
    mkdir -p "$FIX"
    for s in $SEEDS; do
      (cd "$R" && java -cp "$B" SlotConf gen $s 3000 "$B/seed$s") || exit 1
      (cd "$R" && java -cp "$B" SlotConf run "$B/seed$s.script") | cmp -s - "$B/seed$s.obs" || { echo "FAIL ref's run of seed $s differs from its gen"; exit 1; }
      gzip -n -9 < "$B/seed$s.script" > "$FIX/seed$s.script.gz"; gzip -n -9 < "$B/seed$s.obs" > "$FIX/seed$s.obs.gz"
    done
    echo "slotconf: fixtures written to $FIX" ;;
  --check)
    fail=0
    for s in $SEEDS; do
      gzip -dc "$FIX/seed$s.script.gz" > "$B/s.script"
      (cd "$R" && java -cp "$B" SlotConf run "$B/s.script") | cmp -s - <(gzip -dc "$FIX/seed$s.obs.gz") || { echo "FAIL ref differs: seed $s"; fail=1; }
    done
    [ $fail = 0 ] && echo "slotconf --check: $(echo $SEEDS | wc -w) scripts equal ref"; rm -rf "$B"; exit $fail ;;
  --long)
    n=${2:?N}; c=${3:?C}; bin=${4:?BIN}; bad=0
    for s in $(seq 6 "$n"); do
      (cd "$R" && java -cp "$B" SlotConf gen $s "$c" "$B/l") || exit 1
      "$bin" "$B/l.script" | cmp -s - "$B/l.obs" || { echo "DIFF seed $s"; bad=$((bad + 1)); }
    done
    echo "slotconf --long: seeds 6-$n of $c cycles: $bad differ"; rm -rf "$B"; [ $bad = 0 ]; exit ;;
  *) echo "usage: slotconf.sh --fixtures | --check | --long N C BIN"; exit 2 ;;
esac
rm -rf "$B"
